local GildingPressMaker = {}
local PRODUCTS = {
    iron_gilding_press = { name = "Železno pozlačevalno stiskalo", ironCost = 4, woodCost = 2, leatherCost = 1, time = 6, cost = 200, prestige = 5, happiness = 2, description = "Železno pozlačevalno stiskalo za pozlačevanje knjig." },
    bronze_gilding_press = { name = "Bronasto pozlačevalno stiskalo", bronzeCost = 4, ironCost = 1, woodCost = 2, leatherCost = 1, time = 8, cost = 485, prestige = 7, happiness = 3, description = "Bronasto pozlačevalno stiskalo za fino pozlačevanje." },
    silver_gilding_press = { name = "Srebrno pozlačevalno stiskalo", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 12, cost = 1170, prestige = 12, happiness = 4, description = "Srebrno pozlačevalno stiskalo za plemiške knjigoveže." },
    gilded_gilding_press = { name = "Pozlačeno pozlačevalno stiskalo", goldCost = 2, silverCost = 4, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 16, cost = 2520, prestige = 21, happiness = 5, description = "Pozlačeno pozlačevalno stiskalo za dvorne knjigoveže." },
    jewel_set_gilding_press = { name = "Draguljasto pozlačevalno stiskalo", goldCost = 3, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 20, cost = 5400, prestige = 37, happiness = 7, description = "Draguljasto pozlačevalno stiskalo za kraljevske knjigoveže." },
    royal_sovereign_gilding_press = { name = "Kraljevski suvereno pozlačevalno stiskalo", goldCost = 4, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 27, cost = 11500, prestige = 71, happiness = 13, description = "Suvereno pozlačevalno stiskalo z biseri za krono." },
}
local BUILDINGS = {
    gildingpress_workshop = { name = "Pozlačevalna delavnica", cost = { gold = 390, wood = 180, stone = 155, iron = 10 }, upkeep = 8, qualityBonus = 5 },
    gildingpress_house = { name = "Pozlačevalna hiša", cost = { gold = 1340, wood = 365, stone = 300, silver = 8, iron = 9 }, upkeep = 29, qualityBonus = 18 },
    master_gildingpress_atelier = { name = "Mojstrski pozlačevalni atelje", cost = { gold = 3280, wood = 425, stone = 555, silver = 40, gold = 8 }, upkeep = 77, qualityBonus = 30 },
    sovereign_gildingpress_palace = { name = "Suverena pozlačevalna palača", cost = { gold = 13900, wood = 660, stone = 875, gold = 90, jewel = 20 }, upkeep = 266, qualityBonus = 55, prestigeBonus = 50 },
}
GildingPressMaker.ironStock = 16; GildingPressMaker.bronzeStock = 14; GildingPressMaker.woodStock = 12; GildingPressMaker.leatherStock = 10; GildingPressMaker.silverStock = 10; GildingPressMaker.goldStock = 8; GildingPressMaker.jewelStock = 4; GildingPressMaker.pearlStock = 4
GildingPressMaker.productStock = {}; GildingPressMaker.buildings = {}; GildingPressMaker.maker = nil; GildingPressMaker.activeMaking = {}; GildingPressMaker.totalProducts = 0; GildingPressMaker.dayTimer = 0
function GildingPressMaker.init() GildingPressMaker.ironStock=16; GildingPressMaker.bronzeStock=14; GildingPressMaker.woodStock=12; GildingPressMaker.leatherStock=10; GildingPressMaker.silverStock=10; GildingPressMaker.goldStock=8; GildingPressMaker.jewelStock=4; GildingPressMaker.pearlStock=4; GildingPressMaker.productStock={}; GildingPressMaker.buildings={}; GildingPressMaker.maker=nil; GildingPressMaker.activeMaking={}; GildingPressMaker.totalProducts=0; GildingPressMaker.dayTimer=0; print("[GildingPressMaker] Royal Gilding Press Maker System initialized (6 products, 4 buildings)") end
function GildingPressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=595+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GildingPressMaker.maker={name=n or ("Pozlačevalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pozlačevalec najet: %s (spretnost: %d)",GildingPressMaker.maker.name,s),"success") end; return true end
function GildingPressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GildingPressMaker.build(id) local ok,e=GildingPressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GildingPressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GildingPressMaker.getQualityBonus() local b=0; for _,bd in ipairs(GildingPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GildingPressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GildingPressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GildingPressMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GildingPressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GildingPressMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GildingPressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GildingPressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GildingPressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GildingPressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GildingPressMaker.buildings==0 then return false,"Potrebna pozlačevalna delavnica" end; if not GildingPressMaker.maker then return false,"Potreben pozlačevalec" end; return true end
function GildingPressMaker.make(pt,qty) qty=qty or 1; local ok,e=GildingPressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GildingPressMaker.ironStock=GildingPressMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GildingPressMaker.bronzeStock=GildingPressMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GildingPressMaker.woodStock=GildingPressMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GildingPressMaker.leatherStock=GildingPressMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GildingPressMaker.silverStock=GildingPressMaker.silverStock-d.silverCost*qty end; if d.goldCost then GildingPressMaker.goldStock=GildingPressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GildingPressMaker.jewelStock=GildingPressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GildingPressMaker.pearlStock=GildingPressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GildingPressMaker.maker then t=math.max(1,t-math.floor(GildingPressMaker.maker.skill/13)) end; table.insert(GildingPressMaker.activeMaking,{id="gildingpress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GildingPressMaker.completeMaking(m) local q=1.0+(GildingPressMaker.getQualityBonus()/100); if GildingPressMaker.maker then q=q+(GildingPressMaker.maker.skill/140) end; q=math.min(2.5,q); GildingPressMaker.productStock[m.productType]=(GildingPressMaker.productStock[m.productType] or 0)+m.quantity; GildingPressMaker.totalProducts=GildingPressMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GildingPressMaker.maker then GildingPressMaker.maker.itemsMade=GildingPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GildingPressMaker.maker.skill=math.min(100,GildingPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pozlačevalno stiskalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gildingpress.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GildingPressMaker.update(dt) if not _G.state then return end; GildingPressMaker.dayTimer=GildingPressMaker.dayTimer+dt; if GildingPressMaker.dayTimer>=30 then GildingPressMaker.dayTimer=0; for i=#GildingPressMaker.activeMaking,1,-1 do local m=GildingPressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GildingPressMaker.completeMaking(m); table.remove(GildingPressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GildingPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GildingPressMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GildingPressMaker.getStats() return {ironStock=GildingPressMaker.ironStock,bronzeStock=GildingPressMaker.bronzeStock,woodStock=GildingPressMaker.woodStock,leatherStock=GildingPressMaker.leatherStock,silverStock=GildingPressMaker.silverStock,goldStock=GildingPressMaker.goldStock,jewelStock=GildingPressMaker.jewelStock,pearlStock=GildingPressMaker.pearlStock,productStock=GildingPressMaker.productStock,numBuildings=#GildingPressMaker.buildings,hasMaker=GildingPressMaker.maker~=nil,makerName=GildingPressMaker.maker and GildingPressMaker.maker.name or "—",makerSkill=GildingPressMaker.maker and GildingPressMaker.maker.skill or 0,activeMaking=#GildingPressMaker.activeMaking,totalProducts=GildingPressMaker.totalProducts} end
return GildingPressMaker
